import { Box, Fab, IconButton, InputAdornment, Stack, TextField, Tooltip, } from "@mui/material";
import { Camera, File, Image, LinkSimple, PaperPlaneTilt, Smiley, Sticker, User, } from "phosphor-react";
import { useTheme, styled } from "@mui/material/styles";
import React, { useRef, useState } from "react";
import useResponsive from "../../hooks/useResponsive";

import data from "@emoji-mart/data";
import Picker from "@emoji-mart/react";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../webSocketService";
import { showSnackbar, UploadMedia } from "../../redux/slices/app";
import MediaDialog from "./MediaDialog";

const StyledInput = styled(TextField)(({ theme }) => ({
  "& .MuiInputBase-input": {
    paddingTop: "12px !important",
    paddingBottom: "12px !important",
  },
}));

const Actions = [
  {
    color: "#4da5fe",
    icon: <Image size={22} style={{ transition: 'transform 0.2s' }} />,
    y: 102,
    title: "Photo/Video",
    callback: () => { document.getElementById("media-input").click(); },
    hoverEffect: { transform: 'scale(1.2)', cursor: 'pointer' },
  },
  {
    color: "#1b8cfe",
    icon: <Sticker size={22} style={{ transition: 'transform 0.2s' }} />,
    y: 172,
    title: "Stickers",
    callback: (data) => { console.log("Sticker action triggered", data); },
    hoverEffect: { transform: 'scale(1.2)', cursor: 'pointer' },
  },
  {
    color: "#0172e4",
    icon: <Camera size={22} style={{ transition: 'transform 0.2s' }} />,
    y: 242,
    title: "Image",
    callback: (data) => { console.log("Camera action triggered", data); },
    hoverEffect: { transform: 'scale(1.2)', cursor: 'pointer' },
  },
  {
    color: "#0159b2",
    icon: <File size={22} style={{ transition: 'transform 0.2s' }} />,
    y: 312,
    title: "Document",
    callback: () => { document.getElementById("file-input").click(); },
    hoverEffect: { transform: 'scale(1.2)', cursor: 'pointer' },
  },
  {
    color: "#013f7f",
    icon: <User size={22} style={{ transition: 'transform 0.2s' }} />,
    y: 382,
    title: "Contact",
    callback: (data) => { console.log("Contact action triggered", data); },
    hoverEffect: { transform: 'scale(1.2)', cursor: 'pointer' },
  },
];


const ChatInput = ({ openPicker, setOpenPicker, setValue, value, inputRef, handleSendMessage }) => {
  const { current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const dispatch = useDispatch();
  const user_id = window.localStorage.getItem("user_id");
  const { room_id } = useSelector((state) => state.app);
  const [openActions, setOpenActions] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [fileType, setFileType] = useState(null);
  const fileInputRef = useRef(null);

  const [progress, setProgress] = useState(0);
  const [uploading, setUploading] = useState(false);

  const handleKeyPress = (event) => {
    if (event.key === "Enter") {
      event.preventDefault(); // Prevents default Enter behavior
      handleSendMessage(); // Call the function to send the message
    }
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      setSelectedFile(file); // Set the selected file
      setFileType(file.type);
    }
  };

  const handleSendMedia = () => {
    if (selectedFile) {
      const data = {
        file: selectedFile,
      };
      setUploading(true);
      dispatch(UploadMedia(data, (progress) => {
        setProgress(progress);
      })).then((response) => {
        const fileUrl = response.data.fileUrl;
        webSocketService.sendMessage("/app/media_message", JSON.stringify({
          media: fileUrl,
          message: linkify(value),
          conversation_id: room_id,
          from: user_id,
          to: current_conversation.user_id,
          type: fileType.startsWith('image') || fileType.startsWith('video') ? 'MEDIA' : 'DOCUMENT',
          mediaType: fileType.startsWith('image') ? 'image' : fileType.startsWith('video') ? 'video' : selectedFile.name,
        }));
        setSelectedFile(null); // Reset the selected file
        setUploading(false);
        setProgress(0);
      }).catch((error) => {
        setUploading(false);
        setProgress(0);
        dispatch(showSnackbar({ severity: "error", message: "File upload failed!" }));
      });
    }
    setValue("");
  };

  return (
    <>
      <StyledInput
        inputRef={inputRef}
        value={value}
        onChange={(event) => { setValue(event.target.value); }}
        onKeyPress={handleKeyPress}
        fullWidth
        placeholder="Write a message..."
        variant="filled"
        InputProps={{
          disableUnderline: true,
          startAdornment: (
            <Stack sx={{ width: "max-content" }}>
              <Stack
                sx={{
                  position: "relative",
                  display: openActions ? "inline-block" : "none",
                }}
              >
                {Actions.map((el) => (
                  <Tooltip key={el.title} placement="right" title={el.title}>
                    <Fab
                      onClick={() => {
                        setOpenActions(!openActions);
                        el.callback();
                      }}
                      sx={{
                        position: "absolute",
                        top: -el.y,
                        backgroundColor: el.color,
                        transition: '0.1s ease-in-out', // Add smooth transition
                        '&:hover': {
                          transform: 'scale(1.1)',
                        },
                      }}
                      aria-label="add"
                    >
                      {el.icon}
                    </Fab>
                  </Tooltip>
                ))}
              </Stack>
              <InputAdornment>
                <IconButton
                  onClick={() => {
                    setOpenActions(!openActions);
                  }}
                >
                  <LinkSimple />
                </IconButton>
              </InputAdornment>
            </Stack>
          ),
          endAdornment: (
            <Stack sx={{ position: "relative" }}>
              <InputAdornment>
                <IconButton
                  onClick={() => {
                    setOpenPicker(!openPicker);
                  }}
                >
                  <Smiley />
                </IconButton>
              </InputAdornment>
            </Stack>
          ),
        }}
      />
      <input id="media-input"
        hidden
        accept="image/*,video/*"
        type="file"
        onChange={(e) => {
          handleFileSelect(e);
        }}
      />
      <input id="file-input"
        hidden
        accept="application/*,text/*"
        type="file"
        onChange={(e) => {
          handleFileSelect(e);
        }}
      />
      {Boolean(selectedFile) && <MediaDialog
        open={Boolean(selectedFile)}
        handleClose={() => {
          setSelectedFile(null);
        }}
        fileType={fileType}
        handleSend={handleSendMedia}
        file={selectedFile}
        inputRef={inputRef}
        setSelectedFile={setSelectedFile}
        value={value}
        setValue={setValue}
        uploading={uploading}
        progress={progress}
      />}
    </>
  );
};

function linkify(text) {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.replace(
    urlRegex,
    (url) => `<a href="${url}" target="_blank">${url}</a>`
  );
}

function containsUrl(text) {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return urlRegex.test(text);
}

const Footer = () => {
  const theme = useTheme();

  const { current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const dispatch = useDispatch();
  const user_id = window.localStorage.getItem("user_id");
  const isMobile = useResponsive("between", "md", "xs", "sm");
  const { sideBar, room_id } = useSelector((state) => state.app);
  const [openPicker, setOpenPicker] = React.useState(false);
  const [value, setValue] = useState("");
  const inputRef = useRef(null);

  function handleEmojiClick(emoji) {
    const input = inputRef.current;

    if (input) {
      const selectionStart = input.selectionStart;
      const selectionEnd = input.selectionEnd;

      setValue(
        value.substring(0, selectionStart) +
        emoji +
        value.substring(selectionEnd)
      );

      // Move the cursor to the end of the inserted emoji
      input.selectionStart = input.selectionEnd = selectionStart + 1;
    }
  };

  function handleSendMessage() {
    if (value) {
      webSocketService.sendMessage("/app/text_message", JSON.stringify({
        message: linkify(value),
        conversation_id: room_id,
        from: user_id,
        to: current_conversation.user_id,
        type: containsUrl(value) ? "LINK" : "TEXT",
      }));
      setValue("");
    } else {
      dispatch(showSnackbar({ severity: "error", message: "Message cannot be empty" }));
    }
  };

  return (
    <>
      <Box
        zIndex={1}
        sx={{
          position: "relative",
          backgroundColor: "transparent !important",
        }}
      >
        <Box
          p={isMobile ? 1 : 2}
          width={"100%"}
          sx={{
            backgroundColor:
              theme.palette.mode === "light"
                ? "#f5f5f5"
                : theme.palette.background,
            boxShadow: "0px -5px 10px rgba(0, 0, 0, 0.1)",
          }}
        >
          <Stack direction="row" alignItems={"center"} spacing={isMobile ? 1 : 3}>
            <Stack sx={{ width: "100%" }}>
              <Box
                style={{
                  zIndex: 10,
                  position: "fixed",
                  display: openPicker ? "inline" : "none",
                  bottom: 81,
                  right: isMobile ? 20 : sideBar.open ? 420 : 100,
                }}
              >
                <Picker
                  theme={theme.palette.mode}
                  data={data}
                  onEmojiSelect={(emoji) => {
                    handleEmojiClick(emoji.native);
                  }}
                />
              </Box>
              {/* Chat Input */}
              <ChatInput
                inputRef={inputRef}
                value={value}
                setValue={setValue}
                openPicker={openPicker}
                setOpenPicker={setOpenPicker}
                handleSendMessage={handleSendMessage}
              />
            </Stack>
            <Box
              sx={{
                height: 48,
                width: 48,
                backgroundColor: theme.palette.primary.main,
                borderRadius: 1.5,
              }}
            >
              <Stack
                sx={{ height: "100%" }}
                alignItems={"center"}
                justifyContent="center"
              >
                <IconButton
                  onClick={() => {
                    handleSendMessage();
                  }}
                >
                  <PaperPlaneTilt color="#ffffff" />
                </IconButton>
              </Stack>
            </Box>
          </Stack>
        </Box>
      </Box>
    </>
  );
};

export default Footer;